#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
using namespace std;

const int MAX_NODES = 2000;
const int GRID_SIZE = 12;
const int DIRS = 4;
const int INF = 1e9;

int dist[GRID_SIZE][GRID_SIZE];
int gridA[GRID_SIZE][GRID_SIZE];
int gridB[GRID_SIZE][GRID_SIZE];
vector<int> adj[MAX_NODES];
vector<int> exitPoints[GRID_SIZE][GRID_SIZE];

int dr[DIRS] = {0, -1, 0, 1};
int dc[DIRS] = {1, 0, -1, 0};

class HungarianAlgorithm {
public:
    int matchCount;
    int pos[MAX_NODES], rev[MAX_NODES];
    bool visited[MAX_NODES];

    int computeMatching(int n, vector<int> adjList[]) {
        matchCount = 0;
        memset(pos, -1, sizeof(pos));
        memset(rev, -1, sizeof(rev));
        for (int u = 0; u < n; ++u) {
            memset(visited, 0, sizeof(visited));
            if (augment(u, adjList)) ++matchCount;
        }
        return matchCount;
    }

private:
    bool augment(int u, vector<int> adjList[]) {
        for (int v : adjList[u]) {
            if (visited[v]) continue;
            visited[v] = true;
            if (rev[v] == -1 || augment(rev[v], adjList)) {
                pos[u] = v;
                rev[v] = u;
                return true;
            }
        }
        return false;
    }
};

void bfs(int sr, int sc, int n) {
    queue<int> qRow, qCol;
    memset(dist, -1, sizeof(dist));
    qRow.push(sr); qCol.push(sc);
    dist[sr][sc] = 0;
    while (!qRow.empty()) {
        sr = qRow.front(); qRow.pop();
        sc = qCol.front(); qCol.pop();
        for (int d = 0; d < DIRS; ++d) {
            int nr = sr + dr[d], nc = sc + dc[d];
            if (nr >= 0 && nr < GRID_SIZE && nc >= 0 && nc < GRID_SIZE &&
                gridA[nr][nc] >= 0 && dist[nr][nc] < 0) {
                dist[nr][nc] = dist[sr][sc] + 1;
                qRow.push(nr); qCol.push(nc);
            }
        }
    }
}

void expand(int sr, int sc, int count, int maxTime, int &nodeOffset) {
    int visited[GRID_SIZE][GRID_SIZE];
    queue<int> qRow, qCol;
    memset(visited, -1, sizeof(visited));
    qRow.push(sr); qCol.push(sc);
    visited[sr][sc] = 0;
    while (!qRow.empty()) {
        sr = qRow.front(); qRow.pop();
        sc = qCol.front(); qCol.pop();
        if (visited[sr][sc] > min(maxTime, dist[sr][sc])) continue;
        for (int exitIdx : exitPoints[sr][sc]) {
            for (int k = 0; k < count; ++k) {
                adj[nodeOffset + k].push_back(exitIdx);
            }
        }
        if (visited[sr][sc] == min(maxTime, dist[sr][sc])) continue;
        for (int d = 0; d < DIRS; ++d) {
            int nr = sr + dr[d], nc = sc + dc[d];
            if (nr >= 0 && nr < GRID_SIZE && nc >= 0 && nc < GRID_SIZE &&
                gridA[nr][nc] >= 0 && visited[nr][nc] < 0) {
                visited[nr][nc] = visited[sr][sc] + 1;
                qRow.push(nr); qCol.push(nc);
            }
        }
    }
    nodeOffset += count;
}

int main() {
    int n, timeLimit, nodeOffset = 0, exitCount = 0;
    cin >> n >> timeLimit;
    memset(gridA, -1, sizeof(gridA));
    memset(gridB, -1, sizeof(gridB));
    int startR = -1, startC = -1;

    for (int i = 1; i <= n; ++i) {
        string line;
        getline(cin, line);
        for (int j = 1; j <= n; ++j) {
            char c = getchar();
            if (isdigit(c)) gridA[i][j] = c - '0';
            if (c == 'Z') { startR = i; startC = j; }
        }
    }
    if (getchar() == '\n') {}

    bfs(startR, startC, n);

    for (int i = 1; i <= n; ++i) {
        string line;
        getline(cin, line);
        for (int j = 1; j <= n; ++j) {
            char c = getchar();
            if (isdigit(c)) gridB[i][j] = c - '0';
            for (int k = 0; k < gridB[i][j]; ++k) {
                exitPoints[i][j].push_back(exitCount++);
            }
        }
    }
    if (getchar() == '\n') {}

    for (int i = 0; i < GRID_SIZE; ++i)
        for (int j = 0; j < GRID_SIZE; ++j)
            if (dist[i][j] < 0) dist[i][j] = INF;

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (gridA[i][j] > 0) expand(i, j, gridA[i][j], timeLimit, nodeOffset);

    HungarianAlgorithm solver;
    cout << solver.computeMatching(nodeOffset, adj) << endl;
}
